var a=class{static nombrePersona(){return r=>{if(!r.value)return null;let t=r.value.trim().replace(/\s+/g," ");return/^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]{2,60}$/.test(t)?null:{nombrePersonaInvalido:!0}}}static nombreEntidad(){return r=>{if(!r.value)return null;let t=r.value.trim();return t.length<2?{nombreEntidadCorto:!0}:t.replace(/[^a-zA-Z0-9áéíóúÁÉÍÓÚñÑ]/g,"").length<2?{nombreEntidadSinLetras:!0}:null}}static capitalizeText(r){return r&&r.replace(/\s+/g," ").split(" ").map(n=>n.length>0?n.charAt(0).toUpperCase()+n.slice(1).toLowerCase():n).join(" ")+(r.endsWith(" ")?" ":"")}};export{a};
